 * Namespace:   ProdSecureOrchestrator\Domain\ServiceMesh
 * Description: Represents a single micro-service instance (node) in the
 *              ProdSecure Service Mesh.  Tracks health, metadata, and
 *              discovery-related state.  Optimised for immutable value-object
 *              semantics with controlled mutability for heartbeat updates.
 *
 * Author:      Generated by AI – Review before use in production.
 */

declare(strict_types=1);

namespace ProdSecureOrchestrator\Domain\ServiceMesh;

use DateTimeImmutable;
use DateTimeZone;
use JsonSerializable;
use Ramsey\Uuid\Uuid;
use Ramsey\Uuid\UuidInterface;
use Stringable;
use Throwable;

/**
 * @psalm-immutable Except for heartbeat-related counters/time-stamps.
 */
final class ServiceNode implements JsonSerializable, Stringable
{
    /** Maximum age of a heartbeat (in seconds) before a node is considered stale */
    public const HEARTBEAT_TTL = 30;

    private readonly UuidInterface $nodeId;
    private readonly string $serviceName;
    private readonly string $host;
    private readonly int $port;
    private readonly array $tags;
    private readonly array $metadata;
    private ServiceStatus $status;

    private DateTimeImmutable $lastHeartbeatAt;
    private int $successfulHeartbeats = 0;
    private int $failedHeartbeats     = 0;

    /**
     * @throws ServiceNodeException
     */
    public function __construct(
        string         $serviceName,
        string         $host,
        int            $port,
        array          $tags     = [],
        array          $metadata = [],
        ?UuidInterface $nodeId   = null
    ) {
        self::assertValidHost($host);
        self::assertValidPort($port);

        $this->serviceName = $serviceName;
        $this->host        = $host;
        $this->port        = $port;
        $this->tags        = array_unique(array_values($tags));
        $this->metadata    = $metadata;
        $this->nodeId      = $nodeId ?? Uuid::uuid4();
        $this->status      = ServiceStatus::Unknown;
        $this->lastHeartbeatAt = new DateTimeImmutable('now', new DateTimeZone('UTC'));
    }

    public function nodeId(): UuidInterface
    {
        return $this->nodeId;
    }

    public function serviceName(): string
    {
        return $this->serviceName;
    }

    public function host(): string
    {
        return $this->host;
    }

    public function port(): int
    {
        return $this->port;
    }

    /** @return string[] */
    public function tags(): array
    {
        return $this->tags;
    }

    /** @return array<string, scalar|array|null> */
    public function metadata(): array
    {
        return $this->metadata;
    }

    public function status(): ServiceStatus
    {
        // Auto-downgrade to stale if last heartbeat expired
        if ($this->status === ServiceStatus::Healthy &&
            $this->lastHeartbeatAt->getTimestamp() <= time() - self::HEARTBEAT_TTL
        ) {
            $this->status = ServiceStatus::Degraded;
        }

        return $this->status;
    }

    public function lastHeartbeatAt(): DateTimeImmutable
    {
        return $this->lastHeartbeatAt;
    }

    public function successfulHeartbeats(): int
    {
        return $this->successfulHeartbeats;
    }

    public function failedHeartbeats(): int
    {
        return $this->failedHeartbeats;
    }

    /**
     * Performs a liveness probe and updates internal status metrics.
     *
     * The $probe callable must throw an exception or return false for a failed
     * heartbeat, or return true for a successful heartbeat.
     *
     * @throws ServiceNodeException When the probe callable fails.
     */
    public function heartbeat(callable $probe): void
    {
        $this->lastHeartbeatAt = new DateTimeImmutable('now', new DateTimeZone('UTC'));

        try {
            $result = $probe($this);

            if ($result !== true) {
                ++$this->failedHeartbeats;
                $this->status = ServiceStatus::Degraded;

                throw new ServiceNodeException(sprintf(
                    'Health probe for node %s (%s) returned unhealthy state.',
                    $this->nodeId->toString(),
                    $this->uri()
                ));
            }

            ++$this->successfulHeartbeats;
            $this->status = ServiceStatus::Healthy;
        } catch (Throwable $e) {
            ++$this->failedHeartbeats;
            $this->status = ServiceStatus::Unhealthy;

            throw new ServiceNodeException(
                sprintf(
                    'Health probe threw exception for node %s: %s',
                    $this->nodeId->toString(),
                    $e->getMessage()
                ),
                $e->getCode(),
                $e
            );
        }
    }

    public function markDown(): void
    {
        $this->status = ServiceStatus::Unhealthy;
    }

    /**
     * Unique connection string for discovery or monitoring.
     * Example: tcp://192.168.0.10:9200
     */
    public function uri(): string
    {
        return sprintf('tcp://%s:%d', $this->host, $this->port);
    }

    /**
     * Array representation suitable for persistence or JSON.
     *
     * @return array<string, mixed>
     */
    public function toArray(): array
    {
        return [
            'nodeId'              => $this->nodeId->toString(),
            'serviceName'         => $this->serviceName,
            'host'                => $this->host,
            'port'                => $this->port,
            'tags'                => $this->tags,
            'metadata'            => $this->metadata,
            'status'              => $this->status->value,
            'lastHeartbeatAt'     => $this->lastHeartbeatAt->format(DATE_ATOM),
            'successfulHeartbeats'=> $this->successfulHeartbeats,
            'failedHeartbeats'    => $this->failedHeartbeats,
        ];
    }

    public function jsonSerialize(): array
    {
        return $this->toArray();
    }

    public function __toString(): string
    {
        return json_encode($this, JSON_THROW_ON_ERROR);
    }

    /**
     * @param array<string,mixed> $data
     *
     * @throws ServiceNodeException
     */
    public static function fromArray(array $data): self
    {
        $required = ['serviceName', 'host', 'port'];
        foreach ($required as $field) {
            if (!isset($data[$field])) {
                throw new ServiceNodeException(sprintf('Missing required field "%s" on ServiceNode::fromArray()', $field));
            }
        }

        return new self(
            $data['serviceName'],
            $data['host'],
            (int) $data['port'],
            $data['tags']     ?? [],
            $data['metadata'] ?? [],
            isset($data['nodeId']) ? Uuid::fromString($data['nodeId']) : null,
        );
    }

    /**
     * Validate host is a valid IPv4/IPv6 or domain name.
     *
     * @throws ServiceNodeException
     */
    private static function assertValidHost(string $host): void
    {
        if (filter_var($host, FILTER_VALIDATE_IP) !== false) {
            return;
        }

        // Domain name validation
        if (preg_match('/^([a-z0-9-]+\.)*[a-z0-9-]+\.[a-z]{2,}$/i', $host) === 1) {
            return;
        }

        throw new ServiceNodeException(sprintf('Invalid host "%s"', $host));
    }

    /**
     * @throws ServiceNodeException
     */
    private static function assertValidPort(int $port): void
    {
        if ($port < 1 || $port > 65535) {
            throw new ServiceNodeException(sprintf('Invalid port "%d"', $port));
        }
    }
}

/**
 * Backed enum of valid service status states.
 */
enum ServiceStatus: string
{
    case Healthy  = 'healthy';
    case Degraded = 'degraded';
    case Unhealthy = 'unhealthy';
    case Unknown  = 'unknown';
}

/**
 * Domain-specific exception wrapper for node-level errors.
 */
final class ServiceNodeException extends \RuntimeException
{
}
